import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        chars = list(S)
        chars.sort()
        results.append(''.join(chars))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
